import{_ as t,o as n,c as o,ag as a}from"./chunks/framework.B9unkguw.js";const g=JSON.parse('{"title":"Plan View - GeoFence","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-user-guide/plan_view/plan_geofence.md","filePath":"zh/qgc-user-guide/plan_view/plan_geofence.md"}'),i={name:"zh/qgc-user-guide/plan_view/plan_geofence.md"};function l(c,e,r,s,h,d){return n(),o("div",null,e[0]||(e[0]=[a('<h1 id="plan-view-geofence" tabindex="-1">Plan View - GeoFence <a class="header-anchor" href="#plan-view-geofence" aria-label="Permalink to &quot;Plan View - GeoFence&quot;">​</a></h1><p>GeoFences allow you to create virtual regions within which the vehicle can fly, or in which it is <em>not allowed</em> to fly. You can also configure the action taken if you fly outside permitted areas.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><em>QGroundControl</em> will not display the GeoFence options if they are not supported by the connected vehicle firmware.</p></div><h2 id="create-a-geofence" tabindex="-1">Create a GeoFence <a class="header-anchor" href="#create-a-geofence" aria-label="Permalink to &quot;Create a GeoFence&quot;">​</a></h2><p>To create a GeoFence:</p><ol><li><p>Navigate to the Plan View</p></li><li><p>Select the <strong>GeoFence</strong> layer using the <a href="./plan_view.html#layer_switcher">Layer Switcher</a> in the top-right area of the map (or expand the <strong>GeoFence</strong> section in the <a href="./plan_view.html#plan_editor_panel">Plan Editor Panel</a>)</p></li><li><p>Insert a circular or polygon region by pressing the <strong>Circular Fence</strong> or <strong>Polygon Fence</strong> button in the GeoFence section. A new region will be added to the map and to the associated list of fences below the buttons.</p></li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>您可以多次按下按钮创建多个区域，从而能够创建复杂的地理围栏定义。</p></div><ul><li><p>Circular region:</p><ul><li>Move the region by dragging the central dot on the map</li><li>Resize the circle by dragging the dot on the edge of the circle (or you can change the radius value in the fence panel).</li></ul></li><li><p>:::</p><ul><li>Move the vertices by dragging the filled dots</li><li>Create new vertices by clicking the &quot;unfilled&quot; dots on the lines between the filled vertices.</li></ul></li></ul><ol><li>By default new regions are created as <em>inclusion</em> zones (vehicles must stay within the region). Change them to exclusion zones (where the vehicle can&#39;t travel) by unchecking the associated <em>Inclusion</em> checkbox in the fence panel.</li></ol><p>Depending on the firmware, the GeoFence section may also show fence parameters (e.g. breach action) and a <strong>Breach Return Point</strong> that the vehicle will fly to if it breaches the fence.</p><h2 id="edit-delete-a-geofence" tabindex="-1">Edit/Delete a GeoFence <a class="header-anchor" href="#edit-delete-a-geofence" aria-label="Permalink to &quot;Edit/Delete a GeoFence&quot;">​</a></h2><p>You can select a GeoFence region to edit by selecting its <em>Edit</em> radio button in the GeoFence section. You can then edit the region on the map as described in the previous section.</p><p>Regions can be deleted by pressing the associated <strong>Del</strong> button.</p><h2 id="upload-a-geofence" tabindex="-1">Upload a GeoFence <a class="header-anchor" href="#upload-a-geofence" aria-label="Permalink to &quot;Upload a GeoFence&quot;">​</a></h2><p>The GeoFence is uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>',15)]))}const u=t(i,[["render",l]]);export{g as __pageData,u as default};
